function rebuild(): void {
  const token = ++loadToken;
  loader.show();
  if (loadTimer !== null) clearTimeout(loadTimer);
  loadTimer = setTimeout(() => {
    if (token !== loadToken) return;
    vm.updateData(buildParams(view()));
    grid.data = vm;
